export default function VendorPage() { return <PanelShell title="Dashboard" subtitle="Good morning, The Food House. Here is today&apos;s restaurant performance." brand="FoodGo Partner" navItems={nav}><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><MetricCard label="Today's Orders" value="86" change="+12.5% this week" icon={Package} /><MetricCard label="Revenue" value="₹42,680" change="+8.2% this week" icon={IndianRupee} /><MetricCard label="Pending Orders" value="12" change="Needs attention" icon={UtensilsCrossed} /><MetricCard label="Completed" value="74" change="+16.4% this week" icon={CheckCircle2} /><MetricCard label="Rating" value="4.7" change="+0.2 this month" icon={Star} /></div><div className="mt-6 grid gap-5 lg:grid-cols-[1.4fr_0.6fr]"><div className="rounded-2xl border border-border/60 bg-card p-5"><div className="flex items-center justify-between"><h2 className="font-display font-semibold">Revenue overview</h2><select className="rounded-lg border border-border bg-background px-3 py-2 text-sm"><option>Last 7 days</option><option>Last 30 days</option></select></div><div className="mt-8 flex h-56 items-end gap-3 border-b border-l border-border px-4 pb-0 pt-4">{[46, 65, 52, 78, 60, 88, 72, 92, 80].map((height, index) => <div key={index} className="group flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-lg bg-primary/80 transition-all group-hover:bg-primary" style={{ height: `${height}%` }} /><span className="text-[10px] text-muted-foreground">{['Mon','Tue','Wed','Thu','Fri','Sat','Sun','Mon','Tue'][index]}</span></div>)}</div></div><div className="rounded-2xl border border-border/60 bg-card p-5"><h2 className="font-display font-semibold">Popular items</h2><div className="mt-4 space-y-4">{['Chicken Biryani','Paneer Butter Masala','Chicken Tikka','Chicken Momos'].map((item, index) => <div key={item} className="flex items-center gap-3"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10 text-sm font-bold text-primary">{index + 1}</div><span className="flex-1 text-sm font-medium">{item}</span><span className="text-sm text-muted-foreground">{[142, 98, 76, 64][index]} sold</span></div>)}</div><Link href="/vendor/analytics" className="mt-6 flex items-center gap-1 text-sm font-medium text-primary">View analytics <span>→</span></Link></div></div></PanelShell>; }
